245	func (p *Parser) parseForStmt() (*ast.Node, error) {
246		forNode := &ast.Node{
247			Kind: ast.NodeForStmt,
248			Line: p.curToken.Line,
249			Col:  p.curToken.Col,
250		}
251	
252		p.nextToken() // consume 'for'
253	
254		if p.curToken.Type != ast.TokenIdent {
255			return nil, fmt.Errorf("expected iterator variable")
256		}
257	
258		iter := &ast.Node{
259			Kind:  ast.NodeIdent,
260			Value: p.curToken.Value,
261		}
262		forNode.Children = append(forNode.Children, iter)
263		p.nextToken()
264	
265		if p.curToken.Type != ast.TokenIn {
266			return nil, fmt.Errorf("expected 'in' after iterator")
267		}
268	
269		p.nextToken()
270	
271		rng, err := p.parseExpression(0)
272		if err != nil {
273			return nil, err
274		}
275		forNode.Children = append(forNode.Children, rng)
276	
277		if p.curToken.Type != ast.TokenLBrace {
278			return nil, fmt.Errorf("expected '{' for loop body")
279		}
280	
281		body, err := p.parseBlockStmt()
282		if err != nil {
283			return nil, err
284		}
285		forNode.Children = append(forNode.Children, body)
286	
287		return forNode, nil
288	}
