444	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
445		// Handle field access: obj.field
446		if p.curToken.Type == ast.TokenDot {
447			p.nextToken() // consume '.'
448			if p.curToken.Type != ast.TokenIdent {
449				return nil, fmt.Errorf("expected field name after '.'")
450			}
451			return &ast.Node{
452				Kind:     ast.NodeFieldAccess,
453				Value:    p.curToken.Value,
454				Line:     p.curToken.Line,
455				Col:      p.curToken.Col,
456				Children: []*ast.Node{left},
457			}, nil
458		}
459	
460		// Handle array indexing: arr[i]
461		if p.curToken.Type == ast.TokenLBracket {
462			return p.parseIndexExpr(left)
463		}
464	
465		node := &ast.Node{
466			Kind:     ast.NodeBinaryExpr,
467			Line:     p.curToken.Line,
468			Col:      p.curToken.Col,
469			Value:    p.curToken.Value,
470			Children: []*ast.Node{left},
471		}
472	
473		prec := p.curPrecedence()
474		p.nextToken()
475	
476		right, err := p.parseExpression(prec)
477		if err != nil {
478			return nil, err
479		}
480		node.Children = append(node.Children, right)
481	
482		// Handle function calls
483		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
484			call := &ast.Node{
485				Kind:  ast.NodeCallExpr,
486				Value: left.Value,
487			}
488			p.nextToken() // consume '('
489			for p.curToken.Type != ast.TokenRParen {
490				arg, err := p.parseExpression(0)
491				if err != nil {
492					return nil, err
493				}
494				call.Children = append(call.Children, arg)
495				if p.curToken.Type == ast.TokenComma {
496					p.nextToken()
497				}
498			}
499			p.nextToken() // consume ')'
500			return call, nil
501		}
502	
503		return node, nil
504	}
