541	func (p *Parser) parseStructDecl() (*ast.Node, error) {
542		structNode := &ast.Node{
543			Kind: ast.NodeStructDecl,
544			Line: p.curToken.Line,
545			Col:  p.curToken.Col,
546		}
547	
548		p.nextToken() // consume 'struct'
549	
550		if p.curToken.Type != ast.TokenIdent {
551			return nil, fmt.Errorf("expected struct name")
552		}
553	
554		structNode.Value = p.curToken.Value
555		p.nextToken()
556	
557		if p.curToken.Type != ast.TokenLBrace {
558			return nil, fmt.Errorf("expected '{' after struct name")
559		}
560	
561		p.nextToken() // consume '{'
562	
563		// Parse fields
564		for p.curToken.Type != ast.TokenRBrace {
565			field, err := p.parseFieldDecl()
566			if err != nil {
567				return nil, err
568			}
569			structNode.Children = append(structNode.Children, field)
570	
571			if p.curToken.Type == ast.TokenSemicolon {
572				p.nextToken()
573			}
574		}
575	
576		p.nextToken() // consume '}'
577	
578		return structNode, nil
579	}
