619	// parseStructLit parses struct initialization: Point{x: 1, y: 2}
620	func (p *Parser) parseStructLit(name string) (*ast.Node, error) {
621		structLit := &ast.Node{
622			Kind:  ast.NodeStructLit,
623			Value: name,
624			Line:  p.curToken.Line,
625			Col:   p.curToken.Col,
626		}
627	
628		p.nextToken() // consume '{'
629	
630		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
631			if p.curToken.Type != ast.TokenIdent {
632				return nil, fmt.Errorf("expected field name in struct init")
633			}
634	
635			fieldName := p.curToken.Value
636			p.nextToken()
637	
638			if p.curToken.Type != ast.TokenColon {
639				return nil, fmt.Errorf("expected ':' after field name in struct init")
640			}
641	
642			p.nextToken()
643	
644			// Parse field value expression
645			fieldValue, err := p.parseExpression(0)
646			if err != nil {
647				return nil, err
648			}
649	
650			// Create field initialization node
651			fieldInit := &ast.Node{
652				Kind:  ast.NodeFieldDecl,
653				Value: fieldName,
654			}
655			fieldInit.Children = append(fieldInit.Children, fieldValue)
656			structLit.Children = append(structLit.Children, fieldInit)
657	
658			if p.curToken.Type == ast.TokenComma {
659				p.nextToken()
660			}
661		}
662	
663		if p.curToken.Type != ast.TokenRBrace {
664			return nil, fmt.Errorf("expected '}' to close struct init")
665		}
666	
667		p.nextToken() // consume '}'
668	
669		return structLit, nil
670	}
