672	// parseArrayLit parses array literals: [1, 2, 3]
673	func (p *Parser) parseArrayLit() (*ast.Node, error) {
674		node := &ast.Node{
675			Kind:  ast.NodeArrayLit,
676			Line:  p.curToken.Line,
677			Col:   p.curToken.Col,
678			Children: []*ast.Node{},
679		}
680	
681		p.nextToken() // skip '['
682	
683		for p.curToken.Type != ast.TokenRBracket && p.curToken.Type != ast.TokenEOF {
684			elem, err := p.parseExpression(0)
685			if err != nil {
686				return nil, err
687			}
688			node.Children = append(node.Children, elem)
689	
690			if p.curToken.Type == ast.TokenComma {
691				p.nextToken()
692			} else if p.curToken.Type != ast.TokenRBracket {
693				return nil, fmt.Errorf("expected ',' or ']' in array literal")
694			}
695		}
696	
697		if p.curToken.Type != ast.TokenRBracket {
698			return nil, fmt.Errorf("expected ']' to close array literal")
699		}
700	
701		p.nextToken() // skip ']'
702		return node, nil
703	}
704	
705	// parseIndexExpr parses array indexing: arr[i]
706	func (p *Parser) parseIndexExpr(obj *ast.Node) (*ast.Node, error) {
707		node := &ast.Node{
708			Kind:     ast.NodeIndexExpr,
709			Line:     obj.Line,
710			Col:      obj.Col,
711			Children: []*ast.Node{obj},
712		}
713	
714		p.nextToken() // skip '['
715	
716		idx, err := p.parseExpression(0)
717		if err != nil {
718			return nil, err
719		}
720		node.Children = append(node.Children, idx)
721	
722		if p.curToken.Type != ast.TokenRBracket {
723			return nil, fmt.Errorf("expected ']' after array index")
724		}
725	
726		p.nextToken() // skip ']'
727		return node, nil
728	}
