341	// genExpr generates IR for an expression and returns the operand
342	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
343		if node == nil {
344			return Operand{}, fmt.Errorf("nil expression")
345		}
346	
347		switch node.Kind {
348		case ast.NodeIntLit:
349			// Parse integer literal
350			var val int64
351			fmt.Sscanf(node.Value, "%d", &val)
352			return Operand{IsImm: true, ImmVal: val}, nil
353	
354		case ast.NodeStringLit:
355			// String literal
356			return Operand{IsStr: true, SVal: node.Value}, nil
357	
358		case ast.NodeBoolLit:
359			// Boolean literal
360			return Operand{IsBool: true, BVal: node.Value == "true"}, nil
361	
362		case ast.NodeIdent:
363			return Operand{Name: node.Value}, nil
364	
365		case ast.NodeBinaryExpr:
366			return g.genBinaryExpr(node)
367	
368		case ast.NodeUnaryExpr:
369			return g.genUnaryExpr(node)
370	
371		case ast.NodeCallExpr:
372			return g.genCallExpr(node)
373	
374		case ast.NodeFieldAccess:
375			return g.genFieldAccess(node)
376	
377		case ast.NodeArrayLit:
378			return g.genArrayLit(node)
379	
380		case ast.NodeIndexExpr:
381			return g.genIndexExpr(node)
382	
383		default:
384			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
385		}
386	}
