417	// genUnaryExpr generates IR for a unary expression (!, -)
418	func (g *Generator) genUnaryExpr(node *ast.Node) (Operand, error) {
419		if len(node.Children) < 1 {
420			return Operand{}, fmt.Errorf("unary expression requires 1 operand")
421		}
422	
423		operand, err := g.genExpr(node.Children[0])
424		if err != nil {
425			return Operand{}, err
426		}
427	
428		result := g.newTemp()
429		op := node.Value
430	
431		switch op {
432		case "!":
433			// Logical NOT
434			g.emit(Instruction{
435				Op:   OpNot,
436				Dest: result,
437				Src1: operand,
438			})
439		case "-":
440			// Arithmetic negation: negate by subtracting from 0
441			g.emit(Instruction{
442				Op:   OpSub,
443				Dest: result,
444				Src1: Operand{IsImm: true, ImmVal: 0},
445				Src2: operand,
446			})
447		default:
448			return Operand{}, fmt.Errorf("unsupported unary operator: %s", op)
449		}
450	
451		return result, nil
452	}
