454	// genUnrolledFor inlines a constant-range loop without labels or jumps
455	func (g *Generator) genUnrolledFor(iterName string, start, end int64, body *ast.Node) error {
456		for i := start; i < end; i++ {
457			g.emit(Instruction{
458				Op:   OpCopy,
459				Dest: Operand{Name: iterName},
460				Src1: Operand{IsImm: true, ImmVal: i},
461			})
462			if err := g.genStmt(body); err != nil {
463				return err
464			}
465		}
466		return nil
467	}
