469	// genCallExpr generates IR for a function call
470	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
471		if len(node.Children) == 0 {
472			return Operand{}, fmt.Errorf("call expression requires function name")
473		}
474	
475		fnName := node.Children[0].Value
476	
477		// Special handling for syscall
478		if fnName == "syscall" {
479			if len(node.Children) < 2 {
480				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
481			}
482	
483			// syscall number (always first arg after function name)
484			numOp, err := g.genExpr(node.Children[1])
485			if err != nil {
486				return Operand{}, err
487			}
488	
489			// Additional args (starting from index 2)
490			for i := 2; i < len(node.Children); i++ {
491				argOp, err := g.genExpr(node.Children[i])
492				if err != nil {
493					return Operand{}, err
494				}
495				g.emit(Instruction{
496					Op:   OpParam,
497					Src1: argOp,
498				})
499			}
500	
501			// Emit syscall instruction
502			result := g.newTemp()
503			g.emit(Instruction{
504				Op:   OpSyscall,
505				Dest: result,
506				Src1: numOp,
507			})
508	
509			return result, nil
510		}
511	
512		// Emit parameters for regular function calls
513		for i := 1; i < len(node.Children); i++ {
514			argOp, err := g.genExpr(node.Children[i])
515			if err != nil {
516				return Operand{}, err
517			}
518			g.emit(Instruction{
519				Op:   OpParam,
520				Src1: argOp,
521			})
522		}
523	
524		// Emit call
525		result := g.newTemp()
526		g.emit(Instruction{
527			Op:   OpCall,
528			Dest: result,
529			Fn:   fnName,
530		})
531	
532		return result, nil
533	}
