560	func (g *Generator) opcodeFromOp(op string) Opcode {
561		switch op {
562		case "+":
563			return OpAdd
564		case "-":
565			return OpSub
566		case "*":
567			return OpMul
568		case "/":
569			return OpDiv
570		case "==":
571			return OpEq
572		case "!=":
573			return OpNe
574		case "<":
575			return OpLt
576		case ">":
577			return OpGt
578		case "<=":
579			return OpLe
580		case ">=":
581			return OpGe
582		case "&&":
583			return OpAnd
584		case "||":
585			return OpOr
586		default:
587			return OpNoop
588		}
589	}
