727	// isConstIntLit checks if a node is a NodeIntLit and returns its int64 value
728	func isConstIntLit(node *ast.Node) (int64, bool) {
729		if node.Kind != ast.NodeIntLit {
730			return 0, false
731		}
732		var val int64
733		fmt.Sscanf(node.Value, "%d", &val)
734		return val, true
